import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in); int n=s.nextInt(); long[] values=new long[n];for(int i=0;i<n;i++)values[i]=s.nextLong(); CountDownLatch latch=new CountDownLatch(n);AtomicLong sum=new AtomicLong();for(long v:values)new Thread(()->{try{sum.addAndGet(v*v);}finally{latch.countDown();}}).start();latch.await();System.out.println(sum.get()); } }
